for (const item of items) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = 'MarketVision-AI-Report.pdf';
    item.binary.data.mimeType = 'application/pdf';
    item.binary.data.fileExtension = 'pdf';
  }
  try {
    const startedAt = new Date($('Start Run Timer').item.json.runStartedAt);
    const finishedAt = new Date();
    const durationMs = finishedAt - startedAt;
    const minutes = Math.floor(durationMs / 60000);
    const seconds = Math.round((durationMs % 60000) / 1000);
    item.json.runMetricsText = `Run started: ${startedAt.toISOString()} | Run completed: ${finishedAt.toISOString()} | Duration: ${minutes}m ${seconds}s | Token usage & cost: see Azure AI Foundry -> Deployments -> vt-agi-chat -> Monitor tab.`;
  } catch (e) {
    item.json.runMetricsText = 'Run metrics unavailable: ' + e.message;
  }
}
return items;
